<script lang="ts">
  import { onMount } from 'svelte';
  import BillingHistory from './BillingHistory.svelte';
  import { goto } from '$app/navigation';
  import { Button } from '$lib/components/ui/button';
  import { Copy, RefreshCw, QrCode, CheckCircle2, Clock, CircleAlert, ArrowRight, LoaderCircle } from '@lucide/svelte';
  import { request } from './api';
  import { createPoller } from './poll.mjs';
  import { canDeposit, blockedPayment } from './payment-state';
  interface Invoice {id:string;purpose:string;status:string;address:string;network:string;token:string;token_address:string;amount:string;amount_net?:string;fee_amount?:string;credits?:number;price_cents?:number;expires_at:string;created_at:string;}
  let {invoiceId=''}:{invoiceId?:string}=$props();
  let refreshing=$state(false);
  let invoices=$state<Invoice[]>([]);let selected=$state<Invoice|null>(null);let loading=$state(true);let busy=$state(false);let error=$state('');let notice=$state('');let qr=$state('');let qrError=$state('');let initialized=$state(false);let requestedId=$state('');let mounted=false;let sequence=0;let loadFailed=$state(false);let connectionWarning=$state('');
  const list=(value:any):Invoice[]=>Array.isArray(value)?value:value?.invoices||value?.items||[];
  const pending=(invoice:Invoice)=>['pending','processing'].includes(invoice.status);
  const timestamp=(value:string)=>value ? new Date(value).toLocaleString() : '—';
  const statusLabel=(status:string)=>({pending:'Awaiting payment',processing:'Confirming payment',settled:'Payment confirmed',review:'Review required',failed:'Payment not completed',expired:'Quote time elapsed'}[status]||status);
  onMount(()=>{mounted=true;void initialize();const poller=createPoller(signal=>refresh(false,signal),{interval:10000,maxInterval:60000,enabled:()=>!!selected&&pending(selected)&&!busy&&!loading&&document.visibilityState==='visible'});poller.start();return()=>{mounted=false;sequence++;poller.stop();};});
  $effect(()=>{const id=invoiceId;if(initialized&&id&&id!==requestedId)void selectInvoice(id);});
  $effect(()=>{
    const address=selected&&canDeposit(selected)?selected.address:'';qr='';qrError='';
    if(!address)return;
    void import('qrcode').then(module=>module.toDataURL(address,{width:240,margin:3,errorCorrectionLevel:'M',color:{dark:'#000000',light:'#ffffff'}})).then(value=>{if(selected?.address===address)qr=value;}).catch(()=>{if(selected?.address===address)qrError='The QR code could not be generated. Copy the exact address below instead.';});
  });
  async function initialize(){
    loading=true;error='';loadFailed=false;try{invoices=list(await request('/payments/invoices'));const id=invoiceId||invoices[0]?.id;if(id)await selectInvoice(id);initialized=true;}catch(e){loadFailed=true;error=(e as Error).message;}finally{if(mounted)loading=false;}
  }
  async function selectInvoice(id:string){requestedId=id;const current=++sequence;loading=true;error='';notice='';loadFailed=false;selected=null;try{const result=await request(`/payments/invoices/${encodeURIComponent(id)}`);if(mounted&&current===sequence)selected=result;}catch(e){if(mounted&&current===sequence){loadFailed=true;error=(e as Error).message;}}finally{if(mounted&&current===sequence)loading=false;}}
  async function refresh(manual=true,signal?:AbortSignal){
    if(refreshing||busy)return;
    if(!selected){await initialize();return;}const id=selected.id;const current=++sequence;refreshing=true;if(manual){busy=true;error='';notice='';}
    try{const result=await request(`/payments/invoices/${encodeURIComponent(id)}`,undefined,undefined,{},false,{signal});if(!mounted||current!==sequence)return;selected=result;connectionWarning='';invoices=invoices.map(invoice=>invoice.id===id?result:invoice);if(manual)notice='Payment status refreshed from the server.';}
    catch(e){if(mounted&&current===sequence){if(manual)error=(e as Error).message;else connectionWarning='Automatic status refresh is unavailable. Your last confirmed status is shown. Refresh or check payment before taking further action.';}if(!manual)throw e;}finally{refreshing=false;if(manual&&mounted)busy=false;}
  }
  async function notify(){if(!selected||busy||refreshing)return;const id=selected.id;const current=++sequence;busy=true;error='';notice='';try{const result=await request(`/payments/invoices/${encodeURIComponent(id)}/notify`,{});if(!mounted||current!==sequence||selected?.id!==id)return;selected=result;connectionWarning='';invoices=invoices.map(invoice=>invoice.id===id?result:invoice);notice=result.status==='settled'?'The server confirmed your payment.':'Payment check requested. Access and credits are granted only after server confirmation.';}catch(e){error=(e as Error).message;}finally{if(mounted)busy=false;}}
  async function copy(value:string,label:string){try{await navigator.clipboard.writeText(value);notice=`${label} copied.`;}catch{error=`Could not copy ${label.toLowerCase()}. Select and copy the text manually.`;}}
</script>
<div class="payment-page">
  <div class="page-heading"><h1>Payments</h1><p>Recover an invoice, check its status, or complete a payment. One account holds your credits and Premium access.</p></div>
  {#if error}<div class="cloud-alert" role="alert">{error}<Button variant="ghost" size="sm" onclick={initialize}>Reload</Button></div>{/if}
  {#if connectionWarning}<div class="cloud-alert" role="status">{connectionWarning}</div>{/if}
  {#if notice}<div class="cloud-notice" role="status">{notice}</div>{/if}
    <div class="payment-layout"><section class="cloud-panel payment-invoice" aria-label="Invoice payment details">
      {#if loading}<div class="cloud-loading" role="status"><LoaderCircle class="size-5 animate-spin"/>Loading payment details…</div>{:else if selected}{@const invoice=selected}<div class="payment-title"><div><h2>{invoice.purpose==='premium'?'30 days of 6eek Premium':`${invoice.credits?.toLocaleString() ?? 'Generation'} credits`}</h2><p>Invoice {invoice.id}</p></div><span class="status">{statusLabel(invoice.status)}</span></div>
        {#if invoice.status==='settled'}<div class="payment-confirmed"><CheckCircle2 class="size-9"/><h3>Payment confirmed</h3><p>{invoice.purpose==='premium'?'Your prepaid Premium access has been recorded. Renew explicitly when you need more time.':'Your credit purchase has been recorded in your account.'}</p><Button href={invoice.purpose==='premium'?'/premium':'/credits'}>View {invoice.purpose==='premium'?'Premium':'credits'}<ArrowRight class="size-4"/></Button></div>
        {:else if !canDeposit(invoice)}{@const blocked=blockedPayment(invoice)}<div class="payment-review"><CircleAlert class="size-9"/><h3>{blocked.title}</h3><p>{blocked.message}</p><code>{invoice.id}</code><Button variant="outline" onclick={()=>copy(invoice.id,'Invoice ID')}><Copy class="size-4"/>Copy invoice ID</Button><Button disabled={busy||refreshing} variant="outline" onclick={()=>refresh()}><RefreshCw class="size-4"/>Refresh payment status</Button><p class="field-help">No credits or Premium access are granted until the server confirms settlement.</p></div>
        {:else}<div class="payment-rail"><div><span>Required network</span><strong>{invoice.network}</strong></div><div><span>Required token</span><strong>{invoice.token}</strong></div></div><p class="payment-network-note">Send only {invoice.token} on {invoice.network}. A transfer using another network or token cannot settle this invoice.</p>

          <div class="payment-deposit"><div class="payment-qr">{#if qr}<img src={qr} width="240" height="240" alt={`QR code containing only the ${invoice.network} deposit address`}/>{:else if !invoice.address}<CircleAlert class="size-9 text-muted-foreground"/><p>A verified deposit address is not available yet. Check this invoice’s status before sending funds.</p>{:else if qrError}<QrCode class="size-10 text-muted-foreground"/><p>{qrError}</p>{:else}<LoaderCircle class="size-5 animate-spin"/>{/if}<small>Address only. Network and amount are not encoded.</small></div><div class="payment-fields"><span class="payment-field-label">Send exactly</span><div class="payment-value"><code>{invoice.amount}</code><span>{invoice.token}</span><Button variant="ghost" size="icon-sm" aria-label="Copy exact token amount" onclick={()=>copy(invoice.amount,'Amount')}><Copy class="size-4"/></Button></div>{#if invoice.fee_amount}<p class="field-help">The total includes {invoice.fee_amount} {invoice.token} for provider fees and the configured funding reserve. This is included in the total above.</p>{/if}<span class="payment-field-label">Deposit address</span><div class="payment-address"><code>{invoice.address || 'Awaiting verified deposit address'}</code><Button disabled={!invoice.address} variant="ghost" size="icon-sm" aria-label="Copy deposit address" onclick={()=>copy(invoice.address,'Address')}><Copy class="size-4"/></Button></div>{#if invoice.token_address}<span class="payment-field-label">Token contract</span><code class="payment-contract">{invoice.token_address}</code>{/if}</div></div>
          <details class="payment-troubleshooting"><summary>Transferred funds but still waiting?</summary><p>Check your wallet transaction for the exact network, token contract, full invoice amount, and confirmations. Wallet withdrawal or network fees must not reduce the amount arriving at this address. A pending status alone does not identify the cause.</p><p>If the amount is short, the token or network differs, or a transfer failed, contact support with this invoice ID and transaction hash before sending more. Recovery is not guaranteed. Never share wallet keys or seed phrases.</p></details>
          <div class="payment-state" role="status"><Clock class="size-4"/><span>{invoice.status==='processing'?'The server is checking the transfer and its confirmations.':'After transferring, select Check payment to start confirmation.'}</span></div><p class="field-help">Quote time: {timestamp(invoice.expires_at)}. A late deposit can still be reconciled against this invoice’s frozen terms. If you have already paid, check this invoice instead of paying again.</p><div class="payment-actions"><Button disabled={busy||refreshing} onclick={notify}>{#if busy}<LoaderCircle class="size-4 animate-spin"/>{:else}<RefreshCw class="size-4"/>{/if}Check payment</Button><Button variant="outline" disabled={busy||refreshing} onclick={()=>refresh()}>Refresh status</Button></div><p class="field-help">The browser cannot confirm payment. Only the server’s settlement result grants credits or 30-day Premium access. Select Check payment after transferring; status refreshes automatically once processing starts.</p>
        {/if}
      {:else if loadFailed}<div class="cloud-empty compact"><CircleAlert class="size-8"/><h2>Payment details unavailable</h2><p>Reload to recover your invoice history. A connection error does not confirm or cancel a payment.</p><Button variant="outline" onclick={initialize}>Retry loading invoices</Button></div>{:else}<div class="cloud-empty compact"><QrCode class="size-8"/><h2>No payment invoices yet</h2><p>Choose a credit pack or 30 days of Premium to create your first invoice.</p><div class="flex flex-wrap gap-3"><Button href="/credits" variant="outline">Get credits</Button><Button href="/premium">Get Premium</Button></div></div>{/if}
    </section><aside class="payment-history"><BillingHistory/></aside></div>
</div>
<style>
.payment-page,.payment-invoice,.payment-history{min-width:0}.payment-troubleshooting{margin-top:20px;font-size:13px;line-height:1.7}.payment-troubleshooting summary{cursor:pointer;font-weight:500}.payment-troubleshooting p{margin-top:12px;color:var(--muted-foreground)}.payment-troubleshooting summary:focus-visible{outline:2px solid var(--ring);outline-offset:3px}.payment-layout{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(260px,1fr);gap:26px;align-items:start}.payment-title{display:flex;align-items:start;justify-content:space-between;gap:18px;padding-bottom:20px;border-bottom:1px solid var(--border)}.payment-title h2{margin:0}.payment-title p{font-size:12px;color:var(--muted-foreground);margin-top:8px;overflow-wrap:anywhere}.payment-rail{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:24px 0 14px}.payment-rail span{display:block;font-size:12px;color:var(--muted-foreground)}.payment-rail strong{font-size:18px;font-weight:600;display:block;margin-top:5px}.payment-network-note{font-size:13px;padding:13px 15px;background:var(--muted);border:1px solid var(--border);border-radius:var(--radius);margin-bottom:25px}.payment-deposit{display:grid;grid-template-columns:210px minmax(0,1fr);gap:25px;margin:25px 0}.payment-qr{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:13px;align-self:start}.payment-qr img{width:210px;height:210px;max-width:100%;background:white;border:1px solid var(--border);border-radius:var(--radius)}.payment-qr small,.payment-qr p{font-size:12px;color:var(--muted-foreground);text-align:center;line-height:1.7;max-width:215px}.payment-field-label{display:block;font-size:12px;font-weight:500;margin:18px 0 8px}.payment-fields{min-width:0}.payment-fields>.payment-field-label:first-child{margin-top:0}.payment-value{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:10px 0;border-bottom:1px solid var(--border)}.payment-value code{font-size:20px;font-weight:600;overflow-wrap:anywhere}.payment-value>span{font-size:13px;font-weight:500}.payment-value :global(button){margin-left:auto}.payment-address{display:flex;align-items:start;gap:10px;border:1px solid var(--border);background:var(--muted);border-radius:var(--radius);padding:12px}.payment-address>code{flex:1;min-width:0;overflow-wrap:anywhere;font-size:12px;line-height:1.8;user-select:all}.payment-contract{display:block;font-size:12px;color:var(--muted-foreground);overflow-wrap:anywhere;line-height:1.8;user-select:all}.payment-state{display:flex;align-items:center;gap:9px;font-size:13px;border-top:1px solid var(--border);padding-top:22px;margin-top:22px}.payment-actions{display:flex;gap:12px;margin:24px 0 15px;flex-wrap:wrap}.payment-review>code{font-size:12px;overflow-wrap:anywhere;user-select:all}.payment-review,.payment-confirmed{display:flex;align-items:center;flex-direction:column;text-align:center;padding:45px 10px;gap:18px}.payment-review>:global(svg),.payment-confirmed>:global(svg){color:var(--foreground)}.payment-review p,.payment-confirmed p{font-size:13px;color:var(--muted-foreground);max-width:430px}@media(max-width:1150px){.payment-layout{grid-template-columns:1fr}.payment-deposit{grid-template-columns:210px minmax(0,1fr)}}@media(max-width:650px){.payment-deposit{grid-template-columns:1fr}.payment-qr{margin:0 auto 8px}.payment-title{flex-direction:column;gap:13px}.payment-value code{font-size:18px}.payment-invoice{padding:20px}.payment-state{align-items:start}}
</style>
